hin range (for a ranged attack). Roll an attack roll using the attack modifier for the weapon or unarmed attack you're using, and compare the result to the target creature's AC to determine the effect.\n\n**Critical Success** You make a damage roll according to the weapon or unarmed attack and deal double damage.\n\n**Success** You make a damage roll according to the weapon or unarmed attack and deal damage.","availability":null,"requirements":null,"prerequisites":null,"content_source_id":3},"url_aliases":["https://2e.aonprd.com/Actions.aspx?ID=2306"]},{"table":"spell","id":4689,"anchor":{"id":4689,"area":null,"cast":"TWO-ACTIONS","cost":"","name":"Invisibility","rank":2,"uuid":"8105806537970817","range":"touch","rarity":"COMMON","traits":[1447,1433,1899],"defense":null,"targets":"1 creature","trigger":null,"version":"1.0","duration":"10 minutes","meta_data":{"damage":[],"source":{"url":"https://2e.aonprd.com/Spells.aspx?ID=1577","book":"Player Core","page":"339"},"foundry":{"rules":[],"is_focus":false}},"created_at":"2024-03-23T20:47:51.959949+00:00","heightened":{"data":{},"text":[{"text":"The spell lasts 1 minute, but it doesn't end if the target uses a hostile action.","amount":"(4th)"}]},"traditions":["arcane","occult"],"description":"Illusions bend light around the target, rendering it invisible. This makes it undetected to all creatures, though the creatures can attempt to find the target, making it hidden to them instead. If the target uses a hostile action, the spell ends after that hostile action is completed.","availability":null,"requirements":null,"content_source_id":3},"url_aliases":["https://2e.aonprd.com/Spells.aspx?ID=1577"]}],"sources":[{"id":1,"url":"https://paizo.com/products/btq02eoj?Pathfinder-Player-Core","name":"Player Core","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[],"group":"pathfinder-core","deprecated":null},{"id":3,"url":null,"name":"Common Core","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[],"group":"common-core","deprecated":false},{"id":16,"url":"https://paizo.com/products/btq02eav?Pathfinder-Treasure-Vault","name":"Treasure Vault","user_id":null,"is_published":true,"require_key":false,"required_content_sources":[1],"group":"pathfinder-core","deprecated":null}],"source16_counts":{"item":1119,"trait":24,"creature":2},"scope":"Four embedded display text leaves only. Existing operations, selections, modifiers, grants, metadata siblings and saved inventory copies are preserved."}$display099$::jsonb;
  patch jsonb; dependency jsonb; source_spec jsonb; actual jsonb; saved jsonb; changed integer;
  baseline_count integer := 0; terminal_count integer := 0;
  captured jsonb := '{}'; sources_before jsonb := '{}'; queue_before jsonb; queue_after jsonb;
begin
  lock table public.content_update in share mode;
  select coalesce(jsonb_agg(to_jsonb(u) order by u.id),'[]'::jsonb) into queue_before from public.content_update u;
  for patch in select value from jsonb_array_elements(spec->'patches') order by (value->>'id')::bigint loop
    perform 1 from public.item where id=(patch->>'id')::bigint for update;
    if not found then raise exception 'treasure-vault-embedded-prose: owner missing %',patch->>'id'; end if;
  end loop;
  for dependency in select value from jsonb_array_elements(spec->'dependencies') order by value->>'table',(value->>'id')::bigint loop
    if dependency->>'table' not in ('trait','ability_block','spell') then raise exception 'treasure-vault-embedded-prose: unsupported dependency'; end if;
    execute format('select (to_jsonb(d)||jsonb_build_object(''uuid'',d.uuid::text))-''{updated_at,search_tsv}''::text[] from public.%I d where id=$1 for share',dependency->>'table') into actual using (dependency->>'id')::bigint;
    if actual is distinct from dependency->'anchor' then raise exception 'treasure-vault-embedded-prose: dependency drift %/%',dependency->>'table',dependency->>'id'; end if;
  end loop;
  for source_spec in select value from jsonb_array_elements(spec->'sources') order by (value->>'id')::bigint loop
    select to_jsonb(s) into actual from public.content_source s where id=(source_spec->>'id')::bigint for update;
    if actual is null or jsonb_typeof(actual->'meta_data') is distinct from 'object'
      or exists(select 1 from jsonb_each(source_spec) e where actual->e.key is distinct from e.value)
      then raise exception 'treasure-vault-embedded-prose: source drift %',source_spec->>'id'; end if;
    if source_spec->>'id'='16' and exists(select 1 from jsonb_each(spec->'source16_counts') e where actual#>array['meta_data','counts',e.key] is distinct from e.value)
      then raise exception 'treasure-vault-embedded-prose: source counts drift'; end if;
    sources_before:=jsonb_set(sources_before,array[source_spec->>'id'],actual-'updated_at',true);
  end loop;
  if exists(select 1 from public.content_update u where upper(btrim(coalesce(u.status->>'state','PENDING'))) not in ('APPROVED','REJECTED') and (
    (u.type='content-source' and exists(select 1 from jsonb_array_elements(spec->'sources') s where u.ref_id=(s->>'id')::bigint or u.data->>'id'=s->>'id' or lower(btrim(u.data->>'name'))=lower(btrim(s->>'name')) or (s->>'url' is not null and (lower(btrim(u.data->>'url'))=lower(btrim(s->>'url')) or lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(s->>'url'))))))
    or (u.type='item' and exists(select 1 from jsonb_array_elements(spec->'patches') p where u.ref_id=(p->>'id')::bigint or u.data->>'id'=p->>'id' or u.data->>'uuid'=p#>>'{anchor,uuid}' or exists(select 1 from jsonb_array_elements_text(p->'url_aliases') url where lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(url))) or ((u.content_source_id=(p#>>'{anchor,content_source_id}')::bigint or u.data->>'content_source_id'=p#>>'{anchor,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(p#>>'{anchor,name}')))))
    or exists(select 1 from jsonb_array_elements(spec->'dependencies') d where (u.type=replace(d->>'table','_','-') or (d->>'table'='ability_block' and u.type=d#>>'{anchor,type}')) and (u.ref_id=(d->>'id')::bigint or u.data->>'id'=d->>'id' or u.data->>'uuid'=d#>>'{anchor,uuid}' or exists(select 1 from jsonb_array_elements_text(d->'url_aliases') url where lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(url))) or ((u.content_source_id=(d#>>'{anchor,content_source_id}')::bigint or u.data->>'content_source_id'=d#>>'{anchor,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(d#>>'{anchor,name}')))))
  )) then raise exception 'treasure-vault-embedded-prose: pending content requires review'; end if;
  for patch in select value from jsonb_array_elements(spec->'patches') order by (value->>'id')::bigint loop
    select (to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text))-'{updated_at,search_tsv}'::text[] into actual from public.item a where id=(patch->>'id')::bigint;
    if actual is distinct from patch->'anchor' and actual is distinct from patch->'final' then raise exception 'treasure-vault-embedded-prose: unreviewed owner %',patch->>'id'; end if;
    if actual=patch->'anchor' then baseline_count:=baseline_count+1; end if;
    if actual=patch->'final' then terminal_count:=terminal_count+1; end if;
    captured:=jsonb_set(captured,array[patch->>'id'],actual,true);
  end loop;
  if baseline_count<>4 and terminal_count<>4 then raise exception 'treasure-vault-embedded-prose: mixed atomic owner domain'; end if;
  for patch in select value from jsonb_array_elements(spec->'patches') order by (value->>'id')::bigint loop
    select (to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text))-'{updated_at,search_tsv}'::text[] into actual from public.item a where id=(patch->>'id')::bigint;
    if actual is distinct from captured->(patch->>'id') then raise exception 'treasure-vault-embedded-prose: captured baseline drift'; end if;
    if actual=patch->'final' then continue; end if;
    if split_part(patch#>>'{leaves,0,path}', '.',1)='operations' then
      update public.item a set operations=array(select e.value::json from jsonb_array_elements(patch#>'{final,operations}') with ordinality e(value,position) order by e.position)
        where id=(patch->>'id')::bigint and ((to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text))-'{updated_at,search_tsv}'::text[]) is not distinct from captured->(patch->>'id');
    elsif split_part(patch#>>'{leaves,0,path}', '.',1)='meta_data' then
      update public.item a set meta_data=(patch#>'{final,meta_data}')::json
        where id=(patch->>'id')::bigint and ((to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text))-'{updated_at,search_tsv}'::text[]) is not distinct from captured->(patch->>'id');
    else raise exception 'treasure-vault-embedded-prose: unsupported leaf'; end if;
    get diagnostics changed=row_count;
    if changed<>1 then raise exception 'treasure-vault-embedded-prose: captured CAS failed'; end if;
    select (to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text))-'{updated_at,search_tsv}'::text[] into saved from public.item a where id=(patch->>'id')::bigint;
    if saved is distinct from patch->'final' then raise exception 'treasure-vault-embedded-prose: immediate readback drift'; end if;
  end loop;
  for patch in select value from jsonb_array_elements(spec->'patches') loop
    select (to_jsonb(a)||jsonb_build_object('uuid',a.uuid::text))-'{updated_at,search_tsv}'::text[] into saved from public.item a where id=(patch->>'id')::bigint;
    if saved is distinct from patch->'final' then raise exception 'treasure-vault-embedded-prose: final owner readback drift'; end if;
  end loop;
  for dependency in select value from jsonb_array_elements(spec->'dependencies') loop
    execute format('select (to_jsonb(d)||jsonb_build_object(''uuid'',d.uuid::text))-''{updated_at,search_tsv}''::text[] from public.%I d where id=$1',dependency->>'table') into saved using (dependency->>'id')::bigint;
    if saved is distinct from dependency->'anchor' then raise exception 'treasure-vault-embedded-prose: final dependency drift'; end if;
  end loop;
  for source_spec in select value from jsonb_array_elements(spec->'sources') loop
    select to_jsonb(s)-'updated_at' into saved from public.content_source s where id=(source_spec->>'id')::bigint;
    if saved is distinct from sources_before->(source_spec->>'id') then raise exception 'treasure-vault-embedded-prose: source baseline drift'; end if;
  end loop;
  select coalesce(jsonb_agg(to_jsonb(u) order by u.id),'[]'::jsonb) into queue_after from public.content_update u;
  if queue_after is distinct from queue_before then raise exception 'treasure-vault-embedded-prose: queue preservation drift'; end if;
  if exists(select 1 from public.content_update u where upper(btrim(coalesce(u.status->>'state','PENDING'))) not in ('APPROVED','REJECTED') and (
    (u.type='content-source' and exists(select 1 from jsonb_array_elements(spec->'sources') s where u.ref_id=(s->>'id')::bigint or u.data->>'id'=s->>'id' or lower(btrim(u.data->>'name'))=lower(btrim(s->>'name')) or (s->>'url' is not null and (lower(btrim(u.data->>'url'))=lower(btrim(s->>'url')) or lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(s->>'url'))))))
    or (u.type='item' and exists(select 1 from jsonb_array_elements(spec->'patches') p where u.ref_id=(p->>'id')::bigint or u.data->>'id'=p->>'id' or u.data->>'uuid'=p#>>'{anchor,uuid}' or exists(select 1 from jsonb_array_elements_text(p->'url_aliases') url where lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(url))) or ((u.content_source_id=(p#>>'{anchor,content_source_id}')::bigint or u.data->>'content_source_id'=p#>>'{anchor,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(p#>>'{anchor,name}')))))
    or exists(select 1 from jsonb_array_elements(spec->'dependencies') d where (u.type=replace(d->>'table','_','-') or (d->>'table'='ability_block' and u.type=d#>>'{anchor,type}')) and (u.ref_id=(d->>'id')::bigint or u.data->>'id'=d->>'id' or u.data->>'uuid'=d#>>'{anchor,uuid}' or exists(select 1 from jsonb_array_elements_text(d->'url_aliases') url where lower(btrim(u.data#>>'{meta_data,source,url}'))=lower(btrim(url))) or ((u.content_source_id=(d#>>'{anchor,content_source_id}')::bigint or u.data->>'content_source_id'=d#>>'{anchor,content_source_id}') and lower(btrim(u.data->>'name'))=lower(btrim(d#>>'{anchor,name}')))))
  )) then raise exception 'treasure-vault-embedded-prose: final pending content requires review'; end if;
end $repair$;
$historical_original_dual$;
end $historical_dual$;
